1	package io.quarkus.websockets.next.runtime;
2	
3	import org.jboss.logging.Logger;
4	
5	import io.quarkus.arc.InjectableContext.ContextState;
6	import io.quarkus.arc.ManagedContext;
7	import io.quarkus.vertx.core.runtime.context.VertxContextSafetyToggle;
8	import io.quarkus.websockets.next.runtime.WebSocketSessionContext.SessionContextState;
9	import io.smallrye.common.vertx.VertxContext;
10	import io.vertx.core.Context;
11	
12	public class ContextSupport {
13	
14	    private static final Logger LOG = Logger.getLogger(ContextSupport.class);
15	
16	    static final String WEB_SOCKET_CONN_KEY = WebSocketConnectionBase.class.getName();
17	
18	    private final WebSocketConnectionBase connection;
19	    private final SessionContextState sessionContextState;
20	    private final WebSocketSessionContext sessionContext;
21	    private final ManagedContext requestContext;
22	
23	    ContextSupport(WebSocketConnectionBase connection, SessionContextState sessionContextState,
24	            WebSocketSessionContext sessionContext,
25	            ManagedContext requestContext) {
26	        this.connection = connection;
27	        this.sessionContextState = sessionContextState;
28	        this.sessionContext = sessionContext;
29	        this.requestContext = requestContext;
30	    }
31	
32	    void start() {
33	        start(null);
34	    }
35	
36	    void start(ContextState requestContextState) {
37	        LOG.debugf("Start contexts: %s", connection);
38	        startSession();
39	        // Activate a new request context
40	        requestContext.activate(requestContextState);
41	    }
42	
43	    void startSession() {
44	        // Activate the captured session context
45	        sessionContext.activate(sessionContextState);
46	    }
47	
48	    void end(boolean terminateSession) {
49	        end(true, terminateSession);
50	    }
51	
52	    void end(boolean terminateRequest, boolean terminateSession) {
53	        LOG.debugf("End contexts: %s [terminateRequest: %s, terminateSession: %s]", connection, terminateRequest,
54	                terminateSession);
55	        if (terminateRequest) {
56	            requestContext.terminate();
57	        } else {
58	            requestContext.deactivate();
59	        }
60	        if (terminateSession) {
61	            // OnClose - terminate the session context
62	            endSession();
63	        } else {
64	            sessionContext.deactivate();
65	        }
66	    }
67	
68	    void endSession() {
69	        sessionContext.terminate();
70	    }
71	
72	    ContextState currentRequestContextState() {
73	        return requestContext.getStateIfActive();
74	    }
75	
76	    static Context createNewDuplicatedContext(Context context, WebSocketConnectionBase connection) {
77	        Context duplicated = VertxContext.createNewDuplicatedContext(context);
78	        VertxContextSafetyToggle.setContextSafe(duplicated, true);
79	        // We need to store the connection in the duplicated context
80	        // It's used to initialize the synthetic bean later on
81	        duplicated.putLocal(ContextSupport.WEB_SOCKET_CONN_KEY, connection);
82	        LOG.debugf("New vertx duplicated context [%s] created: %s", duplicated, connection);
83	        return duplicated;
84	    }
85	
86	}
