23	class Endpoints {
24	
25	    private static final Logger LOG = Logger.getLogger(Endpoints.class);
26	
27	    static void initialize(Vertx vertx, ArcContainer container, Codecs codecs, WebSocketConnectionBase connection,
28	            WebSocketBase ws, String generatedEndpointClass, Optional<Duration> autoPingInterval, Runnable onClose) {
29	
30	        Context context = vertx.getOrCreateContext();
31	
32	        // Initialize and capture the session context state that will be activated
33	        // during message processing
34	        WebSocketSessionContext sessionContext = sessionContext(container);
35	        SessionContextState sessionContextState = sessionContext.initializeContextState();
36	        ContextSupport contextSupport = new ContextSupport(connection, sessionContextState,
37	                sessionContext(container),
38	                container.requestContext());
39	
40	        // Create an endpoint that delegates callbacks to the endpoint bean
41	        WebSocketEndpoint endpoint = createEndpoint(generatedEndpointClass, context, connection, codecs, contextSupport);
42	
43	        // A broadcast processor is only needed if Multi is consumed by the callback
44	        BroadcastProcessor<Object> textBroadcastProcessor = endpoint.consumedTextMultiType() != null
45	                ? BroadcastProcessor.create()
46	                : null;
47	        BroadcastProcessor<Object> binaryBroadcastProcessor = endpoint.consumedBinaryMultiType() != null
48	                ? BroadcastProcessor.create()
49	                : null;
50	
51	        // NOTE: We always invoke callbacks on a new duplicated context
52	        // and the endpoint is responsible to make the switch if blocking/virtualThread
53	
54	        Context onOpenContext = ContextSupport.createNewDuplicatedContext(context, connection);
55	        onOpenContext.runOnContext(new Handler<Void>() {
56	            @Override
57	            public void handle(Void event) {
58	                endpoint.onOpen().onComplete(r -> {
59	                    if (r.succeeded()) {
60	                        LOG.debugf("@OnOpen callback completed: %s", connection);
61	                        // If Multi is consumed we need to invoke the callback eagerly
62	                        // but after @OnOpen completes
63	                        if (textBroadcastProcessor != null) {
64	                            Multi<Object> multi = textBroadcastProcessor.onCancellation().call(connection::close);
65	                            onOpenContext.runOnContext(new Handler<Void>() {
66	                                @Override
67	                                public void handle(Void event) {
68	                                    endpoint.onTextMessage(multi).onComplete(r -> {
69	                                        if (r.succeeded()) {
70	                                            LOG.debugf("@OnTextMessage callback consuming Multi completed: %s",
71	                                                    connection);
72	                                        } else {
73	                                            logFailure(r.cause(),
74	                                                    "Unable to complete @OnTextMessage callback consuming Multi",
75	                                                    connection);
76	                                        }
77	                                    });
78	                                }
79	                            });
80	                        }
81	                        if (binaryBroadcastProcessor != null) {
82	                            Multi<Object> multi = binaryBroadcastProcessor.onCancellation().call(connection::close);
83	                            onOpenContext.runOnContext(new Handler<Void>() {
84	                                @Override
85	                                public void handle(Void event) {
86	                                    endpoint.onBinaryMessage(multi).onComplete(r -> {
87	                                        if (r.succeeded()) {
88	                                            LOG.debugf("@OnBinaryMessage callback consuming Multi completed: %s",
89	                                                    connection);
90	                                        } else {
91	                                            logFailure(r.cause(),
92	                                                    "Unable to complete @OnBinaryMessage callback consuming Multi",
93	                                                    connection);
94	                                        }
95	                                    });
96	                                }
97	                            });
98	                        }
99	                    } else {
100	                        logFailure(r.cause(), "Unable to complete @OnOpen callback", connection);
101	                    }
102	                });
103	            }
104	        });
105	
106	        if (textBroadcastProcessor == null) {
107	            // Multi not consumed - invoke @OnTextMessage callback for each message received
108	            textMessageHandler(connection, endpoint, ws, onOpenContext, m -> {
109	                endpoint.onTextMessage(m).onComplete(r -> {
110	                    if (r.succeeded()) {
111	                        LOG.debugf("@OnTextMessage callback consumed text message: %s", connection);
112	                    } else {
